toolScript:
// --- Game Configuration & Logic ---
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const micBar = document.getElementById('mic-bar');
        const thresholdLine = document.getElementById('threshold-line');
        const sensSlider = document.getElementById('sensitivity');
        const sensVal = document.getElementById('sens-val');
        // Audio Context Variables
        let audioContext;
        let analyser;
        let dataArray;
        let micStream;
        let audioRunning = false;
        // Game State Variables
        let gameState = 'START'; // START, PLAYING, GAME_OVER
        let score = 0;
        let frameCount = 0;
        let gameSpeed = 3;
        let gravity = 0.6;
        // Sensitivity & Volume
        let jumpThreshold = 60; // Scale 0-100
        let moveThreshold = 10; // Minimum vol to move
        let currentVol = 0;
        // Player Entity
        const player = {
            x: 100,
            y: 300,
            width: 32,
            height: 32,
            dy: 0,
            jumpPower: -13,
            grounded: false,
            color: '#EE6C4D',
            eyes: 'open'
        };
        // World Data
        let platforms = [];
        let particles = [];
        const floorHeight = 50;
        function updateSens(val) {
            jumpThreshold = parseInt(val);
            // Visual update of threshold line (inverse logic for css bottom%)
            thresholdLine.style.bottom = `${jumpThreshold}%`;
            if (val < 30) {
                sensVal.innerText = "Sensitive (Whisper)";
                sensVal.className = "text-xs font-mono font-bold text-blue-600 bg-blue-100 px-2 py-0.5 rounded";
            }
            else if (val > 80) {
                sensVal.innerText = "Hard (Yell)";
                sensVal.className = "text-xs font-mono font-bold text-red-600 bg-red-100 px-2 py-0.5 rounded";
            }
            else {
                sensVal.innerText = "Normal";
                sensVal.className = "text-xs font-mono font-bold text-[#EE6C4D] bg-orange-100 px-2 py-0.5 rounded";
            }
        }
        async function initAudio() {
            try {
                audioContext = new (window.AudioContext || window.webkitAudioContext)();
                micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
                const source = audioContext.createMediaStreamSource(micStream);
                analyser = audioContext.createAnalyser();
                analyser.fftSize = 256;
                source.connect(analyser);
                dataArray = new Uint8Array(analyser.frequencyBinCount);
                audioRunning = true;
                // Initialize visual position
                updateSens(sensSlider.value);
            } catch (err) {
                alert("Microphone access denied. Please allow microphone access to play this game.");
                console.error(err);
            }
        }
        function getVolume() {
            if (!audioRunning) return 0;
            analyser.getByteFrequencyData(dataArray);
            let sum = 0;
            for (let i = 0; i < dataArray.length; i++) {
                sum += dataArray[i];
            }
            let average = sum / dataArray.length;
            // Normalize volume (0-255) to roughly 0-100 scale
            // Multiplier 300/255 exaggerates low volumes slightly for better playability
            return Math.min(100, (average / 255) * 300);
        }
        function initGame() {
            platforms = [];
            // Create initial safe zone floor
            for (let i = 0; i < 5; i++) {
                platforms.push({
                    x: i * 200,
                    y: canvas.height - floorHeight,
                    width: 200,
                    height: floorHeight
                });
            }
            score = 0;
            gameSpeed = 3;
            player.y = canvas.height - floorHeight - player.height;
            player.dy = 0;
            document.getElementById('start-overlay').classList.add('opacity-0', 'pointer-events-none');
            document.getElementById('game-over-overlay').classList.add('hidden');
            gameState = 'PLAYING';
            loop();
        }
        async function startGame() {
            if (!audioContext) {
                await initAudio();
            }
            if (audioContext.state === 'suspended') {
                await audioContext.resume();
            }
            initGame();
        }
        function resetGame() {
            document.getElementById('game-over-overlay').classList.add('hidden');
            initGame();
        }
        // Procedural Generation
        function spawnPlatform() {
            const lastPlat = platforms[platforms.length - 1];
            const gap = 90 + Math.random() * 90; // Gap size
            const width = 150 + Math.random() * 200; // Platform width
            // Height variation
            let y = canvas.height - floorHeight;
            if (Math.random() > 0.5) {
                y -= Math.random() * 120; // Raised platform
            }
            platforms.push({
                x: lastPlat.x + lastPlat.width + gap,
                y: y,
                width: width,
                height: 500 // Extend down so it looks solid
            });
        }
        function createParticles(x, y) {
            for (let i = 0; i < 6; i++) {
                particles.push({
                    x: x,
                    y: y,
                    vx: (Math.random() - 0.5) * 6,
                    vy: (Math.random() - 0.5) * 6,
                    life: 1.0,
                    color: player.color
                });
            }
        }
        function loop() {
            if (gameState !== 'PLAYING') return;
            // --- 1. Audio Input & Visualization ---
            currentVol = getVolume();
            micBar.style.height = `${currentVol}%`;
            if (currentVol > jumpThreshold) micBar.style.backgroundColor = '#EE6C4D';
            else if (currentVol > moveThreshold) micBar.style.backgroundColor = '#3b82f6';
            else micBar.style.backgroundColor = '#94a3b8';
            // --- 2. Player Logic ---
            let moveSpeed = 0;
            // Move: If talking louder than noise floor
            if (currentVol > moveThreshold) {
                moveSpeed = gameSpeed + (currentVol * 0.05); // Faster if louder
                if (moveSpeed > 8) moveSpeed = 8; // Cap speed
            }
            // Jump: Only if grounded and loud enough
            if (currentVol > jumpThreshold && player.grounded) {
                player.dy = player.jumpPower;
                player.grounded = false;
                createParticles(player.x + player.width / 2, player.y + player.height);
                player.eyes = 'wide';
                setTimeout(() => player.eyes = 'open', 500);
            }
            // Gravity
            player.dy += gravity;
            player.y += player.dy;
            // Platform Collision & Scrolling
            player.grounded = false;
            // Score increment when moving
            if (moveSpeed > 0) {
                score += 1;
                document.getElementById('score-display').innerText = Math.floor(score / 10);
            }
            for (let i = 0; i < platforms.length; i++) {
                let p = platforms[i];
                // Scroll world left
                if (moveSpeed > 0) {
                    p.x -= moveSpeed;
                }
                // AABB Collision
                if (
                    player.x < p.x + p.width - 5 && // small buffer for smoother edge feel
                    player.x + player.width > p.x + 5 &&
                    player.y + player.height > p.y &&
                    player.y < p.y + p.height
                ) {
                    // Landing on top
                    if (player.dy >= 0 && player.y + player.height - player.dy <= p.y + 10) {
                        player.grounded = true;
                        player.dy = 0;
                        player.y = p.y - player.height;
                    }
                }
                // Cleanup offscreen platforms
                if (p.x + p.width < -50) {
                    platforms.splice(i, 1);
                    i--;
                }
            }
            // Infinite Generation
            if (platforms.length < 5) {
                spawnPlatform();
            }
            // Death Condition
            if (player.y > canvas.height) {
                gameState = 'GAME_OVER';
                document.getElementById('final-score').innerText = Math.floor(score / 10);
                document.getElementById('game-over-overlay').classList.remove('hidden');
                return;
            }
            // --- 3. Rendering ---
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            // Draw Platforms
            ctx.fillStyle = '#1e293b';
            for (let p of platforms) {
                ctx.beginPath();
                ctx.roundRect(p.x, p.y, p.width, p.height, [8, 8, 0, 0]);
                ctx.fill();
            }
            // Draw Particles
            for (let i = 0; i < particles.length; i++) {
                let pt = particles[i];
                ctx.fillStyle = `rgba(238, 108, 77, ${pt.life})`;
                ctx.beginPath();
                ctx.arc(pt.x, pt.y, 4, 0, Math.PI * 2);
                ctx.fill();
                pt.x += pt.vx;
                pt.y += pt.vy;
                pt.life -= 0.05;
                if (pt.life <= 0) { particles.splice(i, 1); i--; }
            }
            // Draw Player (The Cube)
            ctx.fillStyle = player.color;
            ctx.beginPath();
            // Simple squish effect if moving fast
            let w = player.width;
            let h = player.height;
            if (!player.grounded) { h += 4; w -= 4; } // Stretch jump
            ctx.roundRect(player.x, player.y, w, h, 8);
            ctx.fill();
            // Face Logic
            // Eyes
            ctx.fillStyle = 'white';
            const eyeY = player.y + 10;
            // Left
            ctx.beginPath(); ctx.arc(player.x + 8, eyeY, 6, 0, Math.PI * 2); ctx.fill();
            // Right
            ctx.beginPath(); ctx.arc(player.x + 24, eyeY, 6, 0, Math.PI * 2); ctx.fill();
            // Pupils
            ctx.fillStyle = 'black';
            ctx.beginPath(); ctx.arc(player.x + 8, eyeY, 2, 0, Math.PI * 2); ctx.fill();
            ctx.beginPath(); ctx.arc(player.x + 24, eyeY, 2, 0, Math.PI * 2); ctx.fill();
            // Mouth (Reacts to volume)
            ctx.fillStyle = 'black';
            ctx.beginPath();
            if (currentVol > jumpThreshold) {
                // Screaming O mouth
                ctx.arc(player.x + 16, player.y + 24, 8, 0, Math.PI * 2);
            } else if (currentVol > moveThreshold) {
                // Talking movement
                const openAmount = (currentVol / jumpThreshold) * 6;
                ctx.ellipse(player.x + 16, player.y + 24, 4, Math.max(2, openAmount), 0, 0, Math.PI * 2);
            } else {
                // Smile
                ctx.arc(player.x + 16, player.y + 20, 6, 0.2, Math.PI - 0.2);
            }
            ctx.fill();
            requestAnimationFrame(loop);
        }
        // Key Listener for Restart (R key)
        window.addEventListener('keydown', (e) => {
            if ((e.key === 'r' || e.key === 'R') && gameState === 'GAME_OVER') {
                resetGame();
            }
        });
        // RoundRect Polyfill
        if (CanvasRenderingContext2D.prototype.roundRect === undefined) {
            CanvasRenderingContext2D.prototype.roundRect = function (x, y, w, h, r) {
                if (w < 2 * r) r = w / 2;
                if (h < 2 * r) r = h / 2;
                if (!Array.isArray(r)) r = [r, r, r, r];
                this.beginPath();
                this.moveTo(x + r[0], y);
                this.arcTo(x + w, y, x + w, y + h, r[1]);
                this.arcTo(x + w, y + h, x, y + h, r[2]);
                this.arcTo(x, y + h, x, y, r[3]);
                this.arcTo(x, y, x + w, y, r[0]);
                this.closePath();
                return this;
            };
        }
        // Scroll Logic
        // Placeholder for shared script injection
        if (typeof showHeader !== 'undefined') showHeader();
        if (typeof showFooter !== 'undefined') showFooter();
